def choose_move(observation):
    # Defensive defaults
    dx = 0
    dy = 0

    # Helper to safely get fields
    pos = observation.get("position", {})
    x = pos.get("x", 0)
    y = pos.get("y", 0)

    # Basic heuristic:
    # - If there is a visible resource, move toward closest one.
    # - If there is an enemy within range, move away from it.
    # - Otherwise, nudge towards center of map if available, else stay.

    # Attempt to locate resources
    resources = observation.get("resources", [])
    target = None
    min_dist = None
    for r in resources:
        rx = r.get("x", 0)
        ry = r.get("y", 0)
        if rx is None or ry is None:
            continue
        dist = abs(x - rx) + abs(y - ry)
        if min_dist is None or dist < min_dist:
            min_dist = dist
            target = (rx, ry)

    if target is not None:
        tx, ty = target
        if x < tx:
            dx = 1
        elif x > tx:
            dx = -1
        else:
            dx = 0
        if y < ty:
            dy = 1
        elif y > ty:
            dy = -1
        else:
            dy = 0
        return [dx, dy]

    # If no resource, consider adversaries
    enemies = observation.get("enemies", [])
    threat = None
    for e in enemies:
        ex = e.get("x")
        ey = e.get("y")
        if ex is None or ey is None:
            continue
        dist = abs(x - ex) + abs(y - ey)
        if threat is None or dist < threat[2]:
            threat = (ex, ey, dist)
    if threat is not None:
        ex, ey, dist = threat
        # Move away from threat
        if x < ex:
            dx = -1
        elif x > ex:
            dx = 1
        else:
            dx = 0
        if y < ey:
            dy = -1
        elif y > ey:
            dy = 1
        else:
            dy = 0
        # Clamp to [-1,0,1] (already ensured)
        return [dx, dy]

    # Fallback: move toward center if map size available
    map_size = observation.get("map_size", {})
    mx = map_size.get("x", 0)
    my = map_size.get("y", 0)
    if mx or my:
        cx = mx // 2
        cy = my // 2
        if x < cx:
            dx = 1
        elif x > cx:
            dx = -1
        else:
            dx = 0
        if y < cy:
            dy = 1
        elif y > cy:
            dy = -1
        else:
            dy = 0
        return [dx, dy]

    # Final default
    return [0, 0]

